            JavaFileObjects.forResource("support/AQualifier.java")))
        .processedWith(new AutoFactoryProcessor())
        .compilesWithoutError()
        .and().generatesSources(
            JavaFileObjects.forResource("expected/SimpleClassMixedDepsFactory.java"));
  }

