            + "(testAnnotations = {@" + PROPERTY_ANNOTATION_TEST
            + ".OtherAnnotation(foo = 999)})"),
        ImmutableList.of(TEST_ARRAY_ANNOTATION
            + "(testAnnotations = {@" + PROPERTY_ANNOTATION_TEST
